// Converte cidades em array de items para o loop
const cidadesTexto = $input.first().json.Cidades || '';
const cidades = cidadesTexto.split('\n').map(c => c.trim()).filter(c => c.length > 0);

const totalCidades = cidades.length;

return cidades.map((cidade, index) => ({
  json: {
    cidade: cidade,
    cidade_index: index + 1,
    total_cidades: totalCidades
  }
}));

// Formata mensagem WhatsApp para a cidade
const input = $input.first().json;
const resultados = input.resultados || {};
const cidadeKey = Object.keys(resultados)[0];
const dados = resultados[cidadeKey] || {};

const cidade = dados.cidade || cidadeKey || 'Desconhecida';
const cidadeIndex = dados.cidade_index || 1;
const totalCidades = dados.total_cidades || 1;
const success = dados.success || false;
const faixas = dados.faixas || [];
const error = dados.error || null;
const operadoras = dados.operadoras_disponiveis || [];

let msg = `*📍 COTAÇÃO ${cidadeIndex}/${totalCidades}*\n`;
msg += `*${cidade}*\n`;
msg += `─────────────────────────\n\n`;

if (success && faixas.length > 0) {
  msg += `✅ Cotação Hapvida obtida\n\n`;
  faixas.forEach(f => {
    msg += `${f.faixa_etaria}: ${f.valor}\n`;
  });
} else {
  msg += `❌ ${error || 'Hapvida não disponível'}\n`;
  if (operadoras.length > 0) {
    msg += `\nOperadoras disponíveis:\n`;
    operadoras.forEach(op => {
      msg += `• ${op}\n`;
    });
  }
}

return [{ json: { mensagem: msg } }];
